CREATE OR REPLACE FUNCTION public.fn_assessment_group_results(p_cycle_id uuid, p_establishment_id uuid, p_department_id uuid DEFAULT NULL::uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO '' AS $function$ DECLARE v_cycle record; v_results jsonb; BEGIN SELECT ac.id, ac.tenant_id, ac.questionnaire_template_id, ac.min_respondents_threshold INTO v_cycle FROM public.assessment_cycles ac WHERE ac.id = p_cycle_id AND ac.deleted_at IS NULL; IF v_cycle IS NULL OR (auth.role() IS DISTINCT FROM 'service_role' AND NOT EXISTS (SELECT 1 FROM public.organization_members om WHERE om.tenant_id = v_cycle.tenant_id AND om.user_id = auth.uid() AND om.role IN ('owner','admin','manager','auditor') AND om.deleted_at IS NULL)) THEN RETURN '[]'::jsonb; END IF; SELECT COALESCE(jsonb_agg(to_jsonb(s) ORDER BY s.display_order), '[]'::jsonb) INTO v_results FROM (SELECT qs.id AS section_id, qs.name AS section_name, qs.dimension_code, qs.display_order, count(DISTINCT ar.submission_batch_id) AS respondent_count, CASE WHEN count(DISTINCT ar.submission_batch_id) >= v_cycle.min_respondents_threshold THEN round(avg(CASE WHEN qi.reverse_scored THEN 6 - ar.value ELSE ar.value END)::numeric, 2) END AS avg_score, CASE WHEN count(DISTINCT ar.submission_batch_id) >= v_cycle.min_respondents_threshold THEN min(CASE WHEN qi.reverse_scored THEN 6 - ar.value ELSE ar.value END) END AS min_score, CASE WHEN count(DISTINCT ar.submission_batch_id) >= v_cycle.min_respondents_threshold THEN max(CASE WHEN qi.reverse_scored THEN 6 - ar.value ELSE ar.value END) END AS max_score, CASE WHEN count(DISTINCT ar.submission_batch_id) >= v_cycle.min_respondents_threshold THEN round(stddev(CASE WHEN qi.reverse_scored THEN 6 - ar.value ELSE ar.value END)::numeric, 2) END AS stddev_score, count(DISTINCT ar.submission_batch_id) < v_cycle.min_respondents_threshold AS below_threshold FROM public.questionnaire_sections qs JOIN public.questionnaire_items qi ON qi.section_id = qs.id LEFT JOIN public.assessment_responses ar ON ar.item_id = qi.id AND ar.cycle_id = p_cycle_id AND ar.establishment_id = p_establishment_id AND (p_department_id IS NULL OR ar.department_id = p_department_id) WHERE qs.template_id = v_cycle.questionnaire_template_id GROUP BY qs.id, qs.name, qs.dimension_code, qs.display_order) s; RETURN v_results; END; $function$;
CREATE OR REPLACE FUNCTION public.fn_assessment_cycle_summary(p_cycle_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO '' AS $function$ DECLARE v_cycle record; v_results jsonb; BEGIN SELECT ac.id, ac.tenant_id, ac.questionnaire_template_id, ac.min_respondents_threshold INTO v_cycle FROM public.assessment_cycles ac WHERE ac.id = p_cycle_id AND ac.deleted_at IS NULL; IF v_cycle IS NULL OR (auth.role() IS DISTINCT FROM 'service_role' AND NOT EXISTS (SELECT 1 FROM public.organization_members om WHERE om.tenant_id = v_cycle.tenant_id AND om.user_id = auth.uid() AND om.role IN ('owner','admin','manager','auditor') AND om.deleted_at IS NULL)) THEN RETURN '[]'::jsonb; END IF; SELECT COALESCE(jsonb_agg(to_jsonb(s) ORDER BY s.display_order), '[]'::jsonb) INTO v_results FROM (SELECT qs.id AS section_id, qs.name AS section_name, qs.dimension_code, qs.display_order, count(DISTINCT ar.submission_batch_id) AS respondent_count, CASE WHEN count(DISTINCT ar.submission_batch_id) >= v_cycle.min_respondents_threshold THEN round(avg(CASE WHEN qi.reverse_scored THEN 6 - ar.value ELSE ar.value END)::numeric, 2) END AS avg_score, CASE WHEN count(DISTINCT ar.submission_batch_id) >= v_cycle.min_respondents_threshold THEN min(CASE WHEN qi.reverse_scored THEN 6 - ar.value ELSE ar.value END) END AS min_score, CASE WHEN count(DISTINCT ar.submission_batch_id) >= v_cycle.min_respondents_threshold THEN max(CASE WHEN qi.reverse_scored THEN 6 - ar.value ELSE ar.value END) END AS max_score, CASE WHEN count(DISTINCT ar.submission_batch_id) >= v_cycle.min_respondents_threshold THEN round(stddev(CASE WHEN qi.reverse_scored THEN 6 - ar.value ELSE ar.value END)::numeric, 2) END AS stddev_score, count(DISTINCT ar.submission_batch_id) < v_cycle.min_respondents_threshold AS below_threshold FROM public.questionnaire_sections qs JOIN public.questionnaire_items qi ON qi.section_id = qs.id LEFT JOIN public.assessment_responses ar ON ar.item_id = qi.id AND ar.cycle_id = p_cycle_id WHERE qs.template_id = v_cycle.questionnaire_template_id GROUP BY qs.id, qs.name, qs.dimension_code, qs.display_order) s; RETURN v_results; END; $function$;
CREATE OR REPLACE FUNCTION public.fn_import_risks_from_cycle(p_cycle_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $function$ DECLARE v_user_id uuid := auth.uid(); v_cycle record; v_dim record; v_risk_level public.risk_level; v_risk_id uuid; v_count int := 0; v_skipped int := 0; BEGIN SELECT ac.id, ac.tenant_id, ac.name, ac.status, ac.min_respondents_threshold INTO v_cycle FROM public.assessment_cycles ac WHERE ac.id = p_cycle_id AND ac.deleted_at IS NULL; IF v_user_id IS NULL OR v_cycle IS NULL OR NOT EXISTS (SELECT 1 FROM public.organization_members om WHERE om.tenant_id = v_cycle.tenant_id AND om.user_id = v_user_id AND om.role IN ('owner','admin','manager') AND om.deleted_at IS NULL) THEN RETURN jsonb_build_object('success', false, 'error', 'permission_denied'); END IF; FOR v_dim IN SELECT qs.id AS section_id, qs.name AS section_name, count(DISTINCT ar.submission_batch_id) AS respondent_count, avg(CASE WHEN qi.reverse_scored THEN 6 - ar.value ELSE ar.value END) AS avg_score FROM public.assessment_responses ar JOIN public.questionnaire_items qi ON qi.id = ar.item_id JOIN public.questionnaire_sections qs ON qs.id = qi.section_id WHERE ar.cycle_id = p_cycle_id AND ar.tenant_id = v_cycle.tenant_id GROUP BY qs.id, qs.name LOOP IF v_dim.respondent_count < v_cycle.min_respondents_threshold OR v_dim.avg_score IS NULL THEN v_skipped := v_skipped + 1; CONTINUE; END IF; IF v_dim.avg_score <= 2 THEN v_risk_level := 'low'; ELSIF v_dim.avg_score <= 3 THEN v_risk_level := 'moderate'; ELSIF v_dim.avg_score <= 4 THEN v_risk_level := 'high'; ELSE v_risk_level := 'critical'; END IF; IF v_risk_level NOT IN ('high','critical') OR EXISTS (SELECT 1 FROM public.risk_items ri WHERE ri.cycle_id = p_cycle_id AND ri.section_id = v_dim.section_id AND ri.tenant_id = v_cycle.tenant_id AND ri.deleted_at IS NULL) THEN v_skipped := v_skipped + 1; CONTINUE; END IF; INSERT INTO public.risk_items (tenant_id, cycle_id, section_id, source, category, title, description, initial_risk_level, initial_score, status, priority, identified_by) VALUES (v_cycle.tenant_id, p_cycle_id, v_dim.section_id, 'assessment', 'psychosocial', 'Risco psicossocial: ' || v_dim.section_name, 'Risco identificado a partir do ciclo "' || v_cycle.name || '". Pontuação agregada: ' || round(v_dim.avg_score, 2) || '/5.', v_risk_level, round(v_dim.avg_score, 2), 'identified', CASE WHEN v_risk_level = 'critical' THEN 'urgent' ELSE 'high' END, v_user_id) RETURNING id INTO v_risk_id; INSERT INTO public.risk_audit_log (risk_item_id, actor_id, action, details) VALUES (v_risk_id, v_user_id, 'imported_from_assessment', jsonb_build_object('cycle_id', p_cycle_id, 'section_name', v_dim.section_name, 'avg_score', round(v_dim.avg_score, 2), 'risk_level', v_risk_level::text, 'anonymous_batches', true)); v_count := v_count + 1; END LOOP; RETURN jsonb_build_object('success', true, 'imported', v_count, 'skipped', v_skipped, 'cycle_name', v_cycle.name); END; $function$;
CREATE OR REPLACE FUNCTION public.fn_assessment_participation_stats(p_cycle_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO '' AS $function$ DECLARE v_tenant_id uuid; v_threshold integer; v_result jsonb; BEGIN SELECT ac.tenant_id, ac.min_respondents_threshold INTO v_tenant_id, v_threshold FROM public.assessment_cycles ac WHERE ac.id = p_cycle_id AND ac.deleted_at IS NULL AND (auth.role() = 'service_role' OR EXISTS (SELECT 1 FROM public.organization_members om WHERE om.tenant_id = ac.tenant_id AND om.user_id = auth.uid() AND om.deleted_at IS NULL)); IF v_tenant_id IS NULL THEN RAISE EXCEPTION 'cycle_not_found_or_forbidden'; END IF; WITH invitation_groups AS (SELECT ad.establishment_id, e.name AS establishment_name, ad.department_id, d.name AS department_name, count(ad.id)::integer AS invited_count FROM public.assessment_dispatches ad LEFT JOIN public.establishments e ON e.id = ad.establishment_id LEFT JOIN public.departments d ON d.id = ad.department_id WHERE ad.cycle_id = p_cycle_id AND ad.tenant_id = v_tenant_id AND ad.status = 'sent' GROUP BY ad.establishment_id, e.name, ad.department_id, d.name), response_groups AS (SELECT ar.establishment_id, ar.department_id, count(DISTINCT ar.submission_batch_id)::integer AS responded_count FROM public.assessment_responses ar WHERE ar.cycle_id = p_cycle_id AND ar.tenant_id = v_tenant_id GROUP BY ar.establishment_id, ar.department_id), raw_groups AS (SELECT ig.establishment_id, ig.establishment_name, ig.department_id, ig.department_name, ig.invited_count, COALESCE(rg.responded_count, 0)::integer AS responded_count FROM invitation_groups ig LEFT JOIN response_groups rg ON rg.establishment_id IS NOT DISTINCT FROM ig.establishment_id AND rg.department_id IS NOT DISTINCT FROM ig.department_id), protected_groups AS (SELECT jsonb_build_object('scope', 'group', 'establishment_id', rg.establishment_id, 'establishment_name', rg.establishment_name, 'department_id', rg.department_id, 'department_name', rg.department_name, 'invited_count', CASE WHEN rg.responded_count >= v_threshold THEN rg.invited_count ELSE NULL END, 'responded_count', CASE WHEN rg.responded_count >= v_threshold THEN rg.responded_count ELSE NULL END, 'participation_rate', CASE WHEN rg.responded_count >= v_threshold THEN round(100.0 * rg.responded_count / NULLIF(rg.invited_count, 0), 1) ELSE NULL END, 'below_threshold', rg.responded_count < v_threshold) AS item FROM raw_groups rg), overall_counts AS (SELECT COALESCE((SELECT count(ad.id) FROM public.assessment_dispatches ad WHERE ad.cycle_id = p_cycle_id AND ad.tenant_id = v_tenant_id AND ad.status = 'sent'), 0)::integer AS invited_count, COALESCE((SELECT count(DISTINCT ar.submission_batch_id) FROM public.assessment_responses ar WHERE ar.cycle_id = p_cycle_id AND ar.tenant_id = v_tenant_id), 0)::integer AS responded_count), all_items AS (SELECT 0 AS sort_order, jsonb_build_object('scope', 'overall', 'establishment_id', NULL, 'establishment_name', NULL, 'department_id', NULL, 'department_name', NULL, 'invited_count', CASE WHEN oc.responded_count >= v_threshold THEN oc.invited_count ELSE NULL END, 'responded_count', CASE WHEN oc.responded_count >= v_threshold THEN oc.responded_count ELSE NULL END, 'participation_rate', CASE WHEN oc.responded_count >= v_threshold THEN round(100.0 * oc.responded_count / NULLIF(oc.invited_count, 0), 1) ELSE NULL END, 'below_threshold', oc.responded_count < v_threshold) AS item FROM overall_counts oc UNION ALL SELECT 1, pg.item FROM protected_groups pg) SELECT COALESCE(jsonb_agg(ai.item ORDER BY ai.sort_order), '[]'::jsonb) INTO v_result FROM all_items ai; RETURN v_result; END; $function$;
REVOKE EXECUTE ON FUNCTION public.fn_get_questionnaire_for_token(text) FROM PUBLIC, authenticated, service_role;
REVOKE EXECUTE ON FUNCTION public.fn_submit_assessment(text, text) FROM PUBLIC, authenticated, service_role;
REVOKE EXECUTE ON FUNCTION public.fn_assessment_group_results(uuid, uuid, uuid) FROM PUBLIC, anon;
REVOKE EXECUTE ON FUNCTION public.fn_assessment_cycle_summary(uuid) FROM PUBLIC, anon;
REVOKE EXECUTE ON FUNCTION public.fn_import_risks_from_cycle(uuid) FROM PUBLIC, anon, service_role;
REVOKE EXECUTE ON FUNCTION public.fn_assessment_participation_stats(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.fn_get_questionnaire_for_token(text) TO anon;
GRANT EXECUTE ON FUNCTION public.fn_submit_assessment(text, text) TO anon;
GRANT EXECUTE ON FUNCTION public.fn_assessment_group_results(uuid, uuid, uuid) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_assessment_cycle_summary(uuid) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.fn_import_risks_from_cycle(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_assessment_participation_stats(uuid) TO authenticated, service_role;
REVOKE SELECT, INSERT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER ON TABLE public.assessment_dispatches FROM PUBLIC, anon;
GRANT SELECT, INSERT, UPDATE ON TABLE public.assessment_dispatches TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER ON TABLE public.assessment_dispatches TO service_role;
